// Running min / max / average of the BME280 readings served by the STM32
const d = msg.payload;
if (!d || d.status !== "success") {
    return null;
}
const stats = context.get("stats") || {};
for (const key of ["temperature", "humidity", "pressure"]) {
    const v = Number(d[key]);
    const s = stats[key] || { min: v, max: v, sum: 0, n: 0 };
    s.min = Math.min(s.min, v);
    s.max = Math.max(s.max, v);
    s.sum += v;
    s.n += 1;
    stats[key] = s;
}
context.set("stats", stats);

const row = (name, key) => ({
    Parameter: name,
    Minimum: stats[key].min.toFixed(2),
    Maximum: stats[key].max.toFixed(2),
    Average: (stats[key].sum / stats[key].n).toFixed(2)
});
msg.payload = [
    row("Temperature (°C)", "temperature"),
    row("Humidity (%RH)", "humidity"),
    row("Pressure (hPa)", "pressure")
];
return msg;
